CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sources(id TEXT PRIMARY KEY, citation TEXT NOT NULL, url TEXT, revision TEXT, license TEXT, uncertainty TEXT, note TEXT NOT NULL);
CREATE TABLE materials(id TEXT PRIMARY KEY, name TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('gas','liquid','solid')), composition TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL, builtin INTEGER NOT NULL CHECK(builtin IN(0,1)));
CREATE TABLE material_properties(id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES materials(id), quantity TEXT NOT NULL, unit TEXT NOT NULL, model TEXT NOT NULL CHECK(model IN('constant','table','builtin')), constant_value REAL, temperature_min REAL NOT NULL, temperature_max REAL NOT NULL, pressure_min REAL NOT NULL, pressure_max REAL NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL, UNIQUE(material_id,quantity), CHECK(temperature_min>0 AND temperature_max>=temperature_min AND pressure_min>0 AND pressure_max>=pressure_min));
CREATE TABLE property_samples(property_id TEXT NOT NULL REFERENCES material_properties(id) ON DELETE CASCADE, temperature REAL NOT NULL CHECK(temperature>0), pressure REAL NOT NULL CHECK(pressure>0), value REAL NOT NULL, PRIMARY KEY(property_id,temperature,pressure));
CREATE TABLE solid_properties(material_id TEXT PRIMARY KEY REFERENCES materials(id), conductivity_tensor_json TEXT, note TEXT NOT NULL);
CREATE TABLE fluid_pairs(id TEXT PRIMARY KEY, first_material TEXT NOT NULL REFERENCES materials(id), second_material TEXT NOT NULL REFERENCES materials(id), source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL, CHECK(first_material<>second_material));
CREATE TABLE fluid_pair_properties(id TEXT PRIMARY KEY, pair_id TEXT NOT NULL REFERENCES fluid_pairs(id), quantity TEXT NOT NULL CHECK(quantity IN('surface-tension','contact-angle')), unit TEXT NOT NULL, temperature_min REAL NOT NULL, temperature_max REAL NOT NULL, value REAL NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL, UNIQUE(pair_id,quantity));
CREATE TABLE thermal_contacts(id TEXT PRIMARY KEY, first_material TEXT NOT NULL REFERENCES materials(id), second_material TEXT NOT NULL REFERENCES materials(id), resistance_m2_k_w REAL NOT NULL CHECK(resistance_m2_k_w>=0), temperature_min REAL NOT NULL, temperature_max REAL NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL);
CREATE TABLE surface_radiation(id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES materials(id), emissivity REAL NOT NULL CHECK(emissivity>=0 AND emissivity<=1), temperature_min REAL NOT NULL, temperature_max REAL NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL);
CREATE TABLE boundary_profiles(id TEXT PRIMARY KEY, patch TEXT NOT NULL, quantity TEXT NOT NULL, unit TEXT NOT NULL, samples_json TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL);
CREATE TABLE reference_cases(id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('unvalidated','reference-data')), descriptor_json TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), revision TEXT NOT NULL);
CREATE TABLE reference_values(id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES reference_cases(id), quantity TEXT NOT NULL, unit TEXT NOT NULL, data_json TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, workspace TEXT NOT NULL, snapshot_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE project_materials(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE, material_id TEXT, evaluated_snapshot_json TEXT NOT NULL);
CREATE TABLE runs(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, id TEXT NOT NULL, status TEXT NOT NULL, metadata_json TEXT NOT NULL, PRIMARY KEY(project_id,id));
CREATE TABLE artifacts(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, run_id TEXT NOT NULL, kind TEXT NOT NULL, relative_path TEXT NOT NULL, PRIMARY KEY(project_id,run_id,kind), FOREIGN KEY(project_id,run_id) REFERENCES runs(project_id,id) ON DELETE CASCADE);
CREATE INDEX properties_material ON material_properties(material_id);
CREATE INDEX runs_project ON runs(project_id);
